'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { OPPOSITE_DIRECTIONS, SOUND_SHIELD } from '../../constant'
import { WEAPON_SWORD, WEAPON_BEAM, WEAPON_BOMB } from './common'
import { Walker } from './walker'

// The darknut, read in the ROM (objects $0B and $0C, bank 4 $9B4B) and measured in $5B of level 3: a walker (turning
// at $80) that nothing stuns (its $3D is put back to 0 every frame: the boomerang does nothing). Its shield: the sword,
// the flying sword and a bomb do nothing to it from the front, the way it faces (the sound $0604 $01, measured); from
// the back or a side, they hurt it. Arrows, the magic, the wand and the flame do nothing to it, from any side (see
// docs/rom-analysis.md, Darknut)
const HURT_BY = [WEAPON_SWORD, WEAPON_BEAM, WEAPON_BOMB]

export class Darknut extends Walker {
  // The way the blow goes against the way it faces
  shields (link, { damage, direction, weapon } = {}) {
    const kind = weapon ?? (damage === undefined ? WEAPON_SWORD : undefined)
    if (!HURT_BY.includes(kind)) {
      return true
    }
    return (direction ?? link.direction) === OPPOSITE_DIRECTIONS[this.direction]
  }

  hit (link, weapon = {}) {
    if (!this.shields(link, weapon)) {
      super.hit(link, weapon)
      return
    }
    // Once a thrust
    if (weapon.damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    if (HURT_BY.includes(weapon.weapon ?? WEAPON_SWORD)) {
      soundManager.play(resource.getSound(SOUND_SHIELD))
    }
  }

  stun () {}
}
