'use strict'

import { TILE_WIDTH, TILE_HEIGHT } from '../constant'

// Where Link and the enemies may be in a room of a dungeon (NES x from $20 to $D0, y from $5D to $BD: bank 5,
// $B05E, the values $0346-$0349), relative to the room: inside the wall
export const ROOM = { left: 2 * TILE_WIDTH, right: 13 * TILE_WIDTH, top: 2 * TILE_HEIGHT, bottom: 8 * TILE_HEIGHT }

// A body of a tile at (x, y) is in the room (always true out of the dungeons)
export function isInRoom (map, x, y) {
  if (!map.room) {
    return true
  }
  const rx = x - map.x
  const ry = y - map.y
  return rx >= ROOM.left && rx <= ROOM.right && ry >= ROOM.top && ry <= ROOM.bottom
}
