'use strict'

import resource from '../../resource'
import { TILE_WIDTH, NES_PIXEL, ENEMY_GEL } from '../../constant'
import { Enemy, DIRECTION_VECTORS, DIRECTIONS, STATE_SPAWNING, drawImage, pick, randomInt, canWalkTo } from './common'
import { chooseWay, avoidObstacle } from './walker'

// A small blob of the dungeons, measured in the ROM (object $15, bank 4 $8568): it hops one tile at a time on the
// grid, 1 NES pixel a frame, then waits 8, 24, 40 or 56 frames at random (table $85FA); it turns as the walkers do,
// facing Link at $20 (see walker.js). Anything kills it, the boomerang too; it takes half a heart from Link
const GEL = { life: 0, contactDamage: 0.5, turnRate: 0x20 }
const HOP_SPEED = NES_PIXEL
const PAUSES = [8, 24, 40, 56]
// Out of its cloud ($28 put at 6 by $FA1F), it turns and goes once $28 is under 5 ($85CB): the third frame (measured
// in $2F of level 2). Here it turns the frame before it goes
const FIRST_PAUSE = 1
const MAX_TURN_FRAMES = 255
// Out of a zol cut in two (object $14, made by $B180 in its state $10, put back to 0 by $8522), read in its routine and
// measured in $7B of level 3: a cloud where the zol was ($FA0C: its $28 starts at its slot, then 3 images of 6 frames;
// measured: 24 frames in slot 10, 25 in 11); then ($85BA, $85FE) it slides its way, $FF a frame (3, then 4 NES pixels),
// looking at the scenery every 16 pixels, 4 frames or until something stops it; then it is put on the grid: x + 8 and
// y + 8 cut to 16, y on $xD, which puts it a tile lower than the nearest point of the grid (measured: stopped at once
// on $5D, it is put at $6D; slid down from $5D to $6C, at $7D), and it hops
const SPLIT_CLOUD = 14
const SLIDE_SPEED = 0xff
const SPEED_UNIT = 0x40
const SLIDE_FRAMES = 4
const NES_TOP = 0x3d
const STATE_SLIDING = 'sliding'
// Its colours are those of the walls of the level (sprite palette 3)
export const COLOURS = { level1: 'teal', level2: 'blue', level3: 'green' }
const mod = (value, divisor) => ((value % divisor) + divisor) % divisor
const STATE_HOPPING = 'hopping'

export class Gel extends Enemy {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, GEL, random)
    this.direction = pick(random, DIRECTIONS)
    this.pause = FIRST_PAUSE
    this.turnFrames = randomInt(random, 0, MAX_TURN_FRAMES)
    this.hops = 0
  }

  // One of the two gels a zol becomes, going that way, in that slot
  static split (x, y, direction, slot, random = Math.random) {
    const gel = new Gel(ENEMY_GEL, x, y, random)
    gel.direction = direction
    gel.slot = slot
    gel.split = true
    gel.cloudSteps = slot + SPLIT_CLOUD
    gel.setState(STATE_SPAWNING)
    return gel
  }

  // Narrow for the weapons (bit $40 of $04BF): its centre is x + 4, 4 NES pixels left of the middle of its picture
  get narrow () {
    return true
  }

  // Out of its cloud, it hops (after FIRST_PAUSE); out of a zol, it slides first
  start () {
    this.setState(this.split ? STATE_SLIDING : STATE_HOPPING)
    this.fraction = 0
    this.slid = 0
  }

  slide (map, link) {
    if (this.steps <= SLIDE_FRAMES) {
      this.fraction += SLIDE_SPEED
      const pixels = Math.floor(this.fraction / SPEED_UNIT)
      this.fraction -= pixels * SPEED_UNIT
      const [dx, dy] = DIRECTION_VECTORS[this.direction]
      for (let i = 0; i < pixels; i++) {
        if (this.slid % 16 === 0 && !canWalkTo(map, this.x, this.y, this.direction)) {
          this.toGrid(map, link)
          return
        }
        this.x += dx * NES_PIXEL
        this.y += dy * NES_PIXEL
        this.slid++
      }
      return
    }
    this.toGrid(map, link)
  }

  // On the grid ($859F), then it turns and hops at once
  toGrid (map, link) {
    const x = (this.x - map.x) / NES_PIXEL
    const y = (this.y - map.y) / NES_PIXEL + NES_TOP
    this.x = map.x + ((x + 8) & 0xf0) * NES_PIXEL
    this.y = map.y + ((((y + 8) & 0xf0) | 0x0d) - NES_TOP) * NES_PIXEL
    this.setState(STATE_HOPPING)
    this.pause = 0
    chooseWay(this, map.target ?? link, GEL)
    if (!avoidObstacle(this, map)) {
      this.pause = pick(this.random, PAUSES)
    }
  }

  // Killed by the boomerang
  stun (link) {
    this.hit(link, { damage: 1 })
  }

  act (map, link) {
    this.colour = COLOURS[map.type] ?? 'teal'
    if (this.state === STATE_SLIDING) {
      this.slide(map, link)
      return
    }
    if (this.turnFrames > 0) {
      this.turnFrames--
    }
    if (this.pause > 0) {
      this.pause--
      if (this.pause === 0) {
        chooseWay(this, map.target ?? link, GEL)
        if (!avoidObstacle(this, map)) {
          this.pause = pick(this.random, PAUSES)
        }
      }
      return
    }
    // Up to the next point of the grid (after being pushed back, it may be off it)
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    const offset = mod(dx !== 0 ? this.x - map.x : this.y - map.y, TILE_WIDTH)
    const left = (dx + dy > 0 ? TILE_WIDTH - offset : offset) || TILE_WIDTH
    const step = Math.min(HOP_SPEED, left)
    this.x += dx * step
    this.y += dy * step
    if (step === left) {
      this.hops++
      this.pause = pick(this.random, PAUSES)
    }
  }

  drawBody (context) {
    drawImage(context, resource.getSprite(`gel_${this.colour ?? 'teal'}_move`), this.hops % 2, this.x, this.y, this.width, this.height)
  }
}
